#include <vector>
#include <algorithm>
#include <map>
#include <tuple>
using namespace std;

class Solution {
public:
    int maxDungeonScore(vector<int>& damage, vector<int>& points, int hp, int shield, int hp_boost, int k) {
        int n = damage.size();
        map<tuple<int, int, int, int>, int> memo;
        auto dfs = [&](auto& self, int i, int cur_hp, int cur_shield, int rem_k) -> int {
            if (i == n) return 0;
            auto key = make_tuple(i, cur_hp, cur_shield, rem_k);
            if (memo.count(key)) return memo[key];
            int res = 0;
            int dmg = damage[i];
            int s_dmg = min(cur_shield, dmg);
            int h_dmg = dmg - s_dmg;
            if (cur_hp - h_dmg > 0) {
                res = max(res, points[i] + self(self, i + 1, cur_hp - h_dmg, cur_shield - s_dmg, rem_k));
            }
            if (rem_k > 0) {
                int boosted = cur_hp + hp_boost;
                if (boosted - h_dmg > 0) {
                    res = max(res, points[i] + self(self, i + 1, boosted - h_dmg, cur_shield - s_dmg, rem_k - 1));
                }
            }
            return memo[key] = res;
        };
        return dfs(dfs, 0, hp, shield, k);
    }
};

import java.util.*;

class Solution {
    private Map<String, Integer> memo = new HashMap<>();

    public int maxDungeonScore(int[] damage, int[] points, int hp, int shield, int hp_boost, int k) {
        memo.clear();
        return dfs(damage, points, hp, shield, hp_boost, k, 0);
    }

    private int dfs(int[] damage, int[] points, int curHp, int curShield, int hpBoost, int remK, int i) {
        if (i == damage.length) return 0;
        String key = i + "," + curHp + "," + curShield + "," + remK;
        if (memo.containsKey(key)) return memo.get(key);
        int res = 0;
        int dmg = damage[i];
        int sDmg = Math.min(curShield, dmg);
        int hDmg = dmg - sDmg;
        if (curHp - hDmg > 0) {
            res = Math.max(res, points[i] + dfs(damage, points, curHp - hDmg, curShield - sDmg, hpBoost, remK, i + 1));
        }
        if (remK > 0) {
            int boosted = curHp + hpBoost;
            if (boosted - hDmg > 0) {
                res = Math.max(res, points[i] + dfs(damage, points, boosted - hDmg, curShield - sDmg, hpBoost, remK - 1, i + 1));
            }
        }
        memo.put(key, res);
        return res;
    }
}

var maxDungeonScore = function(damage, points, hp, shield, hp_boost, k) {
    const memo = new Map();
    const n = damage.length;
    function dfs(i, curHp, curShield, remK) {
        if (i === n) return 0;
        const key = `${i},${curHp},${curShield},${remK}`;
        if (memo.has(key)) return memo.get(key);
        let res = 0;
        const dmg = damage[i];
        const sDmg = Math.min(curShield, dmg);
        const hDmg = dmg - sDmg;
        if (curHp - hDmg > 0) {
            res = Math.max(res, points[i] + dfs(i + 1, curHp - hDmg, curShield - sDmg, remK));
        }
        if (remK > 0) {
            const boosted = curHp + hp_boost;
            if (boosted - hDmg > 0) {
                res = Math.max(res, points[i] + dfs(i + 1, boosted - hDmg, curShield - sDmg, remK - 1));
            }
        }
        memo.set(key, res);
        return res;
    }
    return dfs(0, hp, shield, k);
};
